int _tableWidth(List<ModelRowSpec> rows, bool showProvider, bool showCost) {
  if (rows.isEmpty) return 0;
  var width = rows.map((r) => r.modelId.length).reduce(_max) + 2;
  if (showProvider) {
    width += 2 + rows.map((r) => r.provider.length).reduce(_max);
