/// [providerStreamFunction] with the CLI's session id and — for the
/// ChatGPT Codex provider — the credentials-persist callback wired. The
/// DIAL kind additionally picks up the optional `DIAL_API_VERSION`
/// environment value as its `api-version` query parameter and gates the
/// manual cache markers on the endpoint-reported `features.cache` set
/// (unknown models keep the optimistic marker + fallback).
///
/// G2 (gh-178): the returned function is wrapped in the request-build
/// gate — the live model's quadruple is judged at call time, and a mixed
/// triple surfaces the refusal as an [ErrorEvent] INSTEAD of the request
/// (nothing leaves the process). The roles-chain and provider-queue
/// paths never flow through here: they assemble model+key+stream from
/// one [ModelRef] each, coherent by construction.
StreamFunction _catalogStreamFunction(String kind, String key) {
  final inner = config.catalogStreamOverride?.call(kind, key) ??
      providerStreamFunction(
        kind,
        key,
        sessionId: () => _session?.cachedId,
        dialApiVersion: kind == 'dial'
            ? config.envVarValue?.call('DIAL_API_VERSION')
            : null,
        dialCacheMarkersSupported: kind == 'dial' ? _dialCacheFlag : null,
        onChatGptCredentialsRefreshed: kind == 'chatgpt-codex'
            ? _persistChatGptCredentials
            : null,
      );
  return (model, context, {cancelToken}) {
    final refusal = _requestBuildRefusal(model);
    if (refusal != null) {
      final stream = AssistantMessageEventStream();
      stream.push(
        ErrorEvent(
          reason: StopReason.error,
          error: AssistantMessage(
            content: const [],
            api: model.api,
            provider: model.provider,
            model: model.id,
            usage: const Usage(),
            stopReason: StopReason.error,
            errorMessage: refusal.message,
            timestamp: DateTime.now(),
          ),
        ),
      );
      stream.end();
      return stream;
    }
    return inner(model, context, cancelToken: cancelToken);
  };
}

/// The G2 request-build verdict for [model] under the CURRENT wiring:
/// null = coherent, the request may be built. Conservative by design —
/// only provable mixtures refuse (an unresolvable provider identity, a
/// wire mismatch, a rejected binding, or a key that provably belongs to
/// a DIFFERENT configured family while this endpoint's own family
/// resolves a different value). Keys that match no configured family at
/// all (session-only explicit tokens, OAuth blobs, synthetic test keys)
/// and header-auth wiring never refuse.
ModelCoherenceRefusal? _requestBuildRefusal(Model model) {
  final spec = resolveCliProviderSpec(model.provider);
  final activeEntry = _activeCustomName == null
      ? null
      : config.customProviders?.find(_activeCustomName!);
  final identityIsEntry =
      activeEntry != null &&
      sameProviderIdentity(
        model.provider,
        model.provider,
        activeEntry.name,
      ) &&
      model.provider == activeEntry.name;
  final identityKind = spec?.kind ?? (identityIsEntry ? activeEntry!.spec.kind : null);
  final resolvedSpec = spec ?? (identityIsEntry ? activeEntry!.spec : null);
  if (identityKind == null || resolvedSpec == null) {
    return requestCoherenceRefusal(
      RequestCoherenceInput(
