            : const ['gemini-4-argon'];
      },
    );
    final run = await boot(cli);

    io.sendLine('/model kimi/kimi-for-coding');
    await waitForIt(() => cli.agent.state.model.provider == 'kimi');
    io.sendLine('/exit');
    await run;

